try:
    build_query('users; DROP TABLE users', {})
    raise AssertionError('非法表名必须抛 ValueError')
except ValueError as exc:
    assert '表名' in str(exc), '异常信息应说明表名不合法'

try:
    build_query('users', {}, order_by='age; DROP TABLE users')
    raise AssertionError('非法排序字段必须抛 ValueError')
except ValueError as exc:
    assert '排序' in str(exc), '异常信息应说明排序字段不合法'
